pseudocode.ordinary:
before = couriers
for each courier i in before:
  neighbours = all j != i with distance(before[i], before[j]) < R
  neighbourData = []
  contributions = []

  for each neighbour j:
    d = distance(before[i], before[j])
    if falloff is linear:
      strength = A * (R - d) / R
    else if d == 0:
      strength = A
    else:
      strength = min(A, A * (2 * radius)^2 * (1/d^2 - 1/R^2))
    neighbourData.append(j, d, strength)

  for each (j, d, strength) in neighbourData:
    away = normalise(before[i].position - before[j].position)
    if d == 0: away = engineTieDirection(i, j)
    contributions.append(away * strength)
  acceleration[i] = capLength(sum(contributions), A)
  // The preceding neighbour calculation is scene-engine separate().

for each courier i:
  nextVelocity = capLength(before[i].velocity + acceleration[i] * dt, maxSpeed)
  nextPosition = before[i].position + nextVelocity * dt
  after[i] = courier with nextVelocity and nextPosition
